import dev.hua.ptcglive.engine.effect.*;
import java.util.*;

/** Will's pause/resume primitive only; printed cards stay unsupported until match integration is complete. */
public final class CoinOutcomeContinuationTest {
    static class Context extends AttackCoinContinuationTest.Context {
        boolean control=true,deny,forceTails;Boolean reserved;int chosen,flips;
        Context(boolean...coins){super(coins);eligible=false;}
        public boolean canChooseNextCoinOutcome(EffectDefinition e){return control&&reserved==null;}
        public void chooseNextCoinOutcome(EffectDefinition e,boolean heads){if(deny||!canChooseNextCoinOutcome(e))throw new IllegalStateException("Source unavailable");reserved=heads;control=false;chosen++;}
        public CoinResult flipCoins(EffectDefinition e,int n,String operation){
            if(canChooseNextCoinOutcome(e))throw new AssertionError("Coin drawn before its required decision");
            int heads=0;for(int i=0;i<n;i++){boolean value;if(reserved!=null){value=reserved;reserved=null;}else value=coins.remove();if(forceTails)value=false;if(value)heads++;flips++;operations.add(operation+":"+i);}return new CoinResult(n,heads);
        }
    }
    static void check(boolean value,String why){AttackCoinSequenceTest.check(value,why);}
    static void reject(Runnable r){AttackCoinSequenceTest.reject(r);}
    static EffectDefinition coin(String name,int flips){return new EffectDefinition("coin_flip",EffectTarget.SELF,flips==0?Map.of("flips","0","flips_from","DAMAGE_COUNTER_COUNT","bind",name):Map.of("flips",""+flips,"bind",name),List.of(),List.of());}
    static EffectDefinition atom(String name){return AttackCoinContinuationTest.simple(name);}
    static EffectContinuation cursor(Context c,List<EffectDefinition> effects){return new EffectContinuation(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),effects),c);}
    public static void main(String[] args){prefixAndFirstOnly();zero();untilTails();authority();retry();attackPlan();forcedTails();lifecycle();synchronous();System.out.println("CoinOutcomeContinuationTest passed: decision at first actual flip, zero-flip skip, fixed/until-tails sequences, immutable committed prefix, reservation authority/stale rejection, attack-wide retries do not renew one-use choice, forced-tails precedence and synchronous bypass rejection; match integration remains pending");}
    static void prefixAndFirstOnly(){for(boolean heads:List.of(false,true)){
        var c=new Context(false,true,false);var s=cursor(c,List.of(atom("prefix"),coin("first",3),atom("branch"),coin("last",1),atom("suffix")));s.advance();var q=s.pendingCoinOutcomeChoice();
        check(q!=null&&c.prefix==1&&c.flips==0&&c.branch==0&&c.suffix==0&&c.bindings.isEmpty(),"Decision occurred before prefix or after coin");s.advance();check(c.prefix==1&&c.flips==0,"Refresh replayed prefix or drew coin");s.decideCoinOutcome(q.step(),heads);check(c.flips==0&&c.suffix==0,"Decision executed downstream effects");s.advance();
        check(s.complete()&&c.prefix==1&&c.branch==1&&c.suffix==1&&c.flips==4&&c.chosen==1&&c.bindings.get("first").heads()==(heads?2:1)&&c.bindings.get("last").heads()==0,"Choice not limited to first coin or replayed effects");reject(()->s.decideCoinOutcome(q.step(),heads));
    }}
    static void zero(){var c=new Context();var s=cursor(c,List.of(coin("zero",0),atom("prefix"),coin("actual",1)));s.advance();check(s.pendingCoinOutcomeChoice()!=null&&c.bindings.get("zero").flips()==0&&c.prefix==1&&c.chosen==0,"Zero-flip instruction consumed choice");s.decideCoinOutcome(s.pendingCoinOutcomeChoice().step(),false);s.advance();check(s.complete()&&c.flips==1,"Actual coin did not resume");}
    static void untilTails(){var c=new Context();var e=new EffectDefinition("coin_flip",EffectTarget.SELF,Map.of("until","TAILS","bind","until"),List.of(),List.of());var s=cursor(c,List.of(e));s.advance();s.decideCoinOutcome(s.pendingCoinOutcomeChoice().step(),false);s.advance();check(s.complete()&&c.bindings.get("until").flips()==1&&c.flips==1,"Chosen tails failed to terminate sequence");}
    static void authority(){var c=new Context();var s=cursor(c,List.of(atom("prefix"),coin("first",1)));s.advance();var q=s.pendingCoinOutcomeChoice();reject(()->s.decideCoinOutcome(q.step()+1,true));c.deny=true;reject(()->s.decideCoinOutcome(q.step(),true));check(s.pendingCoinOutcomeChoice().equals(q)&&c.chosen==0&&c.flips==0&&c.prefix==1,"Rejected decision changed continuation");c.deny=false;c.control=false;reject(()->s.decideCoinOutcome(q.step(),true));c.control=true;reject(()->s.inject(new TriggeredEffects(EffectTrigger.ON_CARD_PLAYED,List.of(),List.of(atom("suffix"))),c));s.decideCoinOutcome(q.step(),true);s.advance();check(s.complete()&&c.chosen==1,"Valid decision after rejection failed");}
    static void retry(){var c=new Context(false);c.eligible=true;var s=cursor(c,List.of(coin("first",1),atom("suffix")));s.advance();s.decideCoinOutcome(s.pendingCoinOutcomeChoice().step(),true);s.advance();check(s.pendingCoinChoice()!=null&&c.bindings.isEmpty()&&c.chosen==1,"Retry prompt or uncommitted result missing");s.decideCoin(s.pendingCoinChoice().step(),AttackCoinSequence.Decision.RETRY);s.advance();check(s.complete()&&c.bindings.get("first").heads()==0&&c.chosen==1&&c.used==1&&c.flips==2,"Retry renewed one-use chosen result");}
    static void attackPlan(){var c=new Context(false,false,false);var a=new AttackCoinAttempt(r->!r.containsKey("zero")?new AttackCoinAttempt.Instruction("zero",coin("z",0),c):!r.containsKey("actual")?new AttackCoinAttempt.Instruction("actual",coin("a",2),c):null);a.advance(true);var q=a.outcomePrompt();check(q!=null&&q.instruction().equals("actual")&&c.flips==0,"Attack plan chose before zero or after coin");a.advance(true);reject(()->a.decideOutcome(q.revision()+1,true));c.deny=true;reject(()->a.decideOutcome(q.revision(),true));check(a.outcomePrompt().equals(q)&&c.flips==0,"Attack plan invalid decision mutated state");c.deny=false;a.decideOutcome(q.revision(),true);a.advance(true);check(a.prompt()!=null&&c.flips==1,"Expected retry prompt after controlled coin");a.decide(a.prompt().revision(),AttackCoinAttempt.Decision.RETRY);a.advance(true);check(a.complete()&&a.results().get("actual").heads()==0&&c.chosen==1&&c.flips==3,"Whole attack retry renewed choice or retained old result");reject(()->a.decideOutcome(q.revision(),true));}
    static void forcedTails(){var c=new Context();c.forceTails=true;var s=cursor(c,List.of(coin("first",1)));s.advance();s.decideCoinOutcome(s.pendingCoinOutcomeChoice().step(),true);s.advance();check(s.complete()&&c.bindings.get("first").heads()==0&&c.chosen==1,"Forced tails precedence contract broken");}
    static void lifecycle(){var c=new Context();var dispatcher=new EffectLifecycleDispatcher();var program=new EffectProgram(List.of(new TriggeredEffects(EffectTrigger.ON_ACTIVATE,List.of(),List.of(atom("prefix"),coin("first",1),atom("suffix")))));var source=new EffectLifecycleDispatcher.Source(UUID.randomUUID(),"outcome",program);var s=dispatcher.beginActivation(source,1,c);s.advance();check(s.pendingCoinOutcomeChoice()!=null&&c.prefix==1&&c.flips==0,"Lifecycle wrapper dropped coin choice");s.decideCoinOutcome(s.pendingCoinOutcomeChoice().step(),true);s.advance();check(s.complete()&&c.suffix==1&&c.chosen==1,"Lifecycle wrapper did not forward decision");}
    static void synchronous(){var c=new Context();reject(()->CoinFlipPolicy.from(coin("first",1)).flip(c,coin("first",1)));check(c.flips==0&&c.chosen==0,"Synchronous execution bypassed choice");}
}
